63	const sumBasePremiums = (items: Item[]): number => {
64	  let total = 0;
65	  for (const [type, count] of countByType(items)) {
66	    total += groupBasePremium(type, count);
67	  }
68	  return total;
69	};
70	
71	const isHighlyEnchanted = (item: Item): boolean =>
72	  (item.enchantment ?? 0) >= HIGH_ENCH_THRESHOLD;
73	
74	const itemSurchargePct = (item: Item): number =>
75	  (item.cursed ? CURSE_PCT : 0) +
76	  (isHighlyEnchanted(item) ? HIGH_ENCH_PCT : 0);
77	
78	const itemSurcharge = (item: Item): number =>
79	  BASE_PREMIUM[item.type] * itemSurchargePct(item);
80	
81	const itemSurcharges = (items: Item[]): number =>
82	  items.reduce((total, item) => total + itemSurcharge(item), 0);
83	
84	const loyaltyDiscountPct = (customer: Customer): number =>
85	  customer.yearsWithMHPCO >= LOYALTY_YEARS ? LOYALTY_PCT : 0;
86	
87	const followUpDiscountPct = (priorQuoteCount: number): number =>
88	  priorQuoteCount > 0 ? FOLLOW_UP_PCT : 0;
89	
90	const policyBaseMultiplier = (customer: Customer, priorQuoteCount: number): number =>
91	  1 + FIRST_INSURANCE_PCT - loyaltyDiscountPct(customer) - followUpDiscountPct(priorQuoteCount);
92	
93	const computeQuotePremium = (items: Item[], customer: Customer, priorQuoteCount: number): number => {
94	  const policyBase = sumBasePremiums(items);
95	  return roundUp(
96	    policyBase * policyBaseMultiplier(customer, priorQuoteCount) + itemSurcharges(items) + PROCESSING_FEE,
97	  );
98	};
99	
100	type Policy = { items: Item[]; remainingCap: number };
101	
102	const makePolicy = (items: Item[]): Policy => {
103	  const insuranceSum = items.reduce((sum, item) => sum + insuranceValueOf(item.type), 0);
104	  return { items, remainingCap: insuranceSum * CAP_MULTIPLIER };
105	};
106	
107	const reimbursableAmount = (item: Item, damageAmount: number): number =>
108	  (item.enchantment ?? 0) >= HIGH_ENCH_PAYOUT_THRESHOLD
109	    ? damageAmount * HIGH_ENCH_PAYOUT_FACTOR
110	    : damageAmount;
111	
112	const payoutForDamage = (item: Item, damage: Damage): number =>
113	  Math.max(0, reimbursableAmount(item, damage.amount) - DEDUCTIBLE);
114	
115	const validateDamage = (damage: Damage): void => {
116	  if (damage.amount < 0) throw new Error(`negative damage amount: ${damage.amount}`);
117	};
118	
119	const matchDamageToItem = (items: Item[], damage: Damage, consumed: Set<number>): number => {
120	  const idx = items.findIndex((item, i) => !consumed.has(i) && item.type === damage.itemType);
121	  if (idx === -1) throw new Error(`damage references item not in policy: ${damage.itemType}`);
122	  return idx;
123	};
124	
125	const processClaim = (policy: Policy, incident: Incident): ClaimResult => {
126	  let totalPayout = 0;
127	  const consumed = new Set<number>();
128	  for (const damage of incident.damages) {
129	    validateDamage(damage);
130	    const idx = matchDamageToItem(policy.items, damage, consumed);
131	    consumed.add(idx);
132	    const capRemaining = policy.remainingCap - totalPayout;
133	    totalPayout += Math.min(payoutForDamage(policy.items[idx], damage), capRemaining);
134	  }
135	  policy.remainingCap -= totalPayout;
136	  return { payout: roundDown(totalPayout), remainingCap: policy.remainingCap };
137	};
138	
139	const validateItems = (items: Item[]): void => {
140	  for (const item of items) {
141	    if (!(item.type in BASE_PREMIUM)) {
142	      throw new Error(`unknown item type: ${item.type}`);
143	    }
144	  }
145	};
146	
147	export const runScenario = (scenario: Scenario): ScenarioResult => {
148	  const results: StepResult[] = [];
149	  const policies: Policy[] = [];
150	  let priorQuoteCount = 0;
151	  for (const step of scenario.steps) {
152	    if (step.op === "quote") {
153	      validateItems(step.items);
154	      results.push({ premium: computeQuotePremium(step.items, scenario.customer, priorQuoteCount) });
155	      policies.push(makePolicy(step.items));
156	      priorQuoteCount++;
157	    } else {
158	      const policy = policies[step.policy];
159	      results.push(processClaim(policy, step.incident));
160	    }
161	  }
162	  return { results };
163	};
